import os
import json
import time
import logging
from typing import Optional, Dict, Any, Tuple, List
from flask import Flask, request, jsonify, send_from_directory, Response
from flask_cors import CORS
from dotenv import load_dotenv
import bleach
from werkzeug.exceptions import HTTPException
import signal
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
import threading
from functools import lru_cache
from datetime import datetime, timedelta

# Optional: Neon Postgres
try:
    import psycopg2
    import psycopg2.extras
    from psycopg2.pool import ThreadedConnectionPool
    HAS_PG = True
except Exception:
    HAS_PG = False

# Import Exa + Cerebras
try:
    from cerebras.cloud.sdk import Cerebras
    from exa_py import Exa
    import tiktoken
    DEPENDENCIES_AVAILABLE = True
except ImportError as e:
    print(f"Warning: Missing dependencies: {e}")
    Cerebras = None
    Exa = None
    tiktoken = None
    DEPENDENCIES_AVAILABLE = False

load_dotenv()
app = Flask(__name__)
CORS(app, max_age=86400)
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger("max-speed-app")

# MAX SPEED CONFIG
class MaxSpeedConfig:
    MODEL_NAME = "gpt-oss-120b"
    MAX_COMPLETION_TOKENS = 131_072
    TEMPERATURE = 0.01
    TOP_P = 0.1
    REASONING_EFFORT = "low"
    REQUEST_TIMEOUT = 60
    MAX_SEARCH_RESULTS = 1000
    SEARCH_TIMEOUT = 10
    LIVECRAWL = "always"
    MAX_WORKERS = 64
    CACHE_TTL_SECONDS = 86400

config = MaxSpeedConfig()

# CLIENT MANAGER
class ClientManager:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if getattr(self, "_initialized", False):
            return
        self.cerebras = None
        self.exa = None
        self.tokenizer = None
        self.pg_pool: Optional[ThreadedConnectionPool] = None
        self.pg_dsn = None
        self._init_models()
        self._init_cache_backends()
        self._initialized = True

    def _init_models(self):
        if Cerebras and os.getenv("CEREBRAS_API_KEY"):
            self.cerebras = Cerebras(
                api_key=os.getenv("CEREBRAS_API_KEY"),
                timeout=config.REQUEST_TIMEOUT,
                max_retries=1
            )
        if tiktoken:
            self.tokenizer = tiktoken.get_encoding("gpt2")
        if Exa and os.getenv("EXA_API_KEY"):
            self.exa = Exa(
                api_key=os.getenv("EXA_API_KEY"),
                timeout=config.SEARCH_TIMEOUT
            )

    def _init_cache_backends(self):
        dsn_env = os.getenv("NEON_DATABASE_URL")
        if not dsn_env:
            raw = os.getenv("NEON_PSQL_DSN")
            if raw and raw.startswith("postgresql://"):
                dsn_env = raw
        if HAS_PG and dsn_env and dsn_env.startswith("postgresql://"):
            try:
                self.pg_dsn = dsn_env
                self.pg_pool = ThreadedConnectionPool(
                    minconn=1, maxconn=20, dsn=self.pg_dsn
                )
                self._ensure_pg_schema()
                logger.info("Postgres cache initialized (Neon).")
            except Exception as e:
                logger.warning(f"Postgres init failed: {e}")
                self.pg_pool = None

    def _ensure_pg_schema(self):
        conn = self.pg_pool.getconn()
        try:
            with conn, conn.cursor() as cur:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS ai_cache (
                        cache_key TEXT PRIMARY KEY,
                        value JSONB NOT NULL,
                        expire_at TIMESTAMPTZ NOT NULL
                    );
                """)
                cur.execute("CREATE INDEX IF NOT EXISTS idx_ai_cache_expire ON ai_cache (expire_at);")
        finally:
            self.pg_pool.putconn(conn)

clients = ClientManager()

# TOKEN COUNT
@lru_cache(maxsize=10000)
def count_tokens(text: str) -> int:
    if clients.tokenizer:
        return len(clients.tokenizer.encode(text))
    return max(1, len(text) // 4)

# SANITIZE / VALIDATE
def fast_sanitize(text: str) -> str:
    return bleach.clean(text or "", tags=[], strip=True).strip()

def fast_validate(query: str) -> bool:
    return bool(query and len(query) > 0)

# CACHE LAYER
class Cache:
    _mem_lock = threading.Lock()
    _mem_cache: Dict[str, Tuple[float, Dict[str, Any]]] = {}

    @staticmethod
    def _now_ts() -> float:
        return time.time()

    @staticmethod
    def _ttl_to_ts(ttl_seconds: int) -> float:
        return time.time() + ttl_seconds

    @classmethod
    def get(cls, key: str) -> Optional[Dict[str, Any]]:
        # Postgres cache
        if clients.pg_pool:
            try:
                conn = clients.pg_pool.getconn()
                try:
                    with conn, conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                        cur.execute(
                            "SELECT value FROM ai_cache WHERE cache_key=%s AND expire_at > NOW()",
