                        )
                        row = cur.fetchone()
                        if row and row.get("value"):
                            return row["value"]
                finally:
                    clients.pg_pool.putconn(conn)
            except Exception as e:
                logger.warning(f"PG cache get error: {e}")

        # Memory cache
        with cls._mem_lock:
            item = cls._mem_cache.get(key)
            if item:
                expire_ts, data = item
                if expire_ts > cls._now_ts():
                    return data
                else:
                    cls._mem_cache.pop(key, None)
        return None

