    def set(cls, key: str, value: Dict[str, Any], ttl_seconds: int = config.CACHE_TTL_SECONDS):
        # Postgres cache
        if clients.pg_pool:
            try:
                conn = clients.pg_pool.getconn()
                try:
                    with conn, conn.cursor() as cur:
                        expire_interval = f"INTERVAL '{ttl_seconds} seconds'"
                        cur.execute(
                            f"""
                            INSERT INTO ai_cache (cache_key, value, expire_at)
                            VALUES (%s, %s, NOW() + {expire_interval})
                            ON CONFLICT (cache_key)
                            DO UPDATE SET value = EXCLUDED.value, expire_at = EXCLUDED.expire_at
                            """,
                            (key, json.dumps(value))
                        )
                finally:
                    clients.pg_pool.putconn(conn)
            except Exception as e:
                logger.warning(f"PG cache set error: {e}")

        # Memory cache
        with cls._mem_lock:
            if len(cls._mem_cache) > 5000:
                cls._mem_cache.pop(next(iter(cls._mem_cache)))
            cls._mem_cache[key] = (cls._ttl_to_ts(ttl_seconds), value)

# EXA SEARCH
def exa_fast_search(query: str):
    return clients.exa.search_and_contents(
        query,
        num_results=config.MAX_SEARCH_RESULTS,
        text=True,
        use_autoprompt=True,
        type="auto",
        livecrawl=config.LIVECRAWL,
        text_contents_options={
            "max_characters": 50000,
            "include_html_tags": False
        },
    )

def process_results_fast(exa_results) -> Tuple[List[Dict[str, Any]], List[str]]:
    if not exa_results or not getattr(exa_results, "results", None):
        return [], []
    results = exa_results.results[:config.MAX_SEARCH_RESULTS]

    processed, contexts = [], []

    def proc(r):
        title = r.title or "No title"
        text = r.text or ""
        return {
            "title": title,
            "snippet": (text[:500] + ("..." if len(text) > 500 else "")) if text else "No content",
            "url": r.url
        }, f"Source: {title}\n{text[:5000]}"

    with ThreadPoolExecutor(max_workers=config.MAX_WORKERS) as ex:
        futs = [ex.submit(proc, r) for r in results]
        for f in as_completed(futs, timeout=5):
            try:
                p, c = f.result()
                processed.append(p)
                contexts.append(c)
            except Exception:
                pass

    return processed, contexts

