```python
import os
import json
import time
import logging
from typing import Optional, Dict, Any, Tuple, List
from flask import Flask, request, jsonify, send_from_directory, Response
from flask_cors import CORS
from dotenv import load_dotenv
import bleach
from werkzeug.exceptions import HTTPException, NotFound
import signal
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
import threading
from functools import lru_cache
from datetime import datetime
import hashlib

try:
    import psycopg2
    import psycopg2.extras
    from psycopg2.pool import ThreadedConnectionPool
    HAS_PG = True
except Exception:
    HAS_PG = False

try:
    from cerebras.cloud.sdk import Cerebras
    from exa_py import Exa
    import tiktoken
    DEPENDENCIES_AVAILABLE = True
except Exception:
    Cerebras = None
    Exa = None
    tiktoken = None
    DEPENDENCIES_AVAILABLE = False

load_dotenv()
app = Flask(__name__, static_folder=".", static_url_path="")
CORS(app, max_age=86400)
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")
logger = logging.getLogger("max-speed-app")

class MaxSpeedConfig:
    MODEL_NAME = "llama3.1-70b"
    MAX_COMPLETION_TOKENS = 8192
    TEMPERATURE = 0.1
    TOP_P = 0.9
    REASONING_EFFORT = "low"
    REQUEST_TIMEOUT = 60
    MAX_SEARCH_RESULTS = 50
    SEARCH_TIMEOUT = 10
    LIVECRAWL = "always"
    MAX_WORKERS = 64
    CACHE_TTL_SECONDS = 86400
    MAX_CONTEXT_CHARS = 200000
    SSE_RETRY_MS = 2000

config = MaxSpeedConfig()

class ClientManager:
    _instance = None
    _lock = threading.Lock()
    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance
    def __init__(self):
        if getattr(self, "_initialized", False):
            return
        self.cerebras = None
        self.exa = None
        self.tokenizer = None
        self.pg_pool: Optional[ThreadedConnectionPool] = None
        self.pg_dsn = None
        self._init_models()
        self._init_cache_backends()
        self._initialized = True
    def _init_models(self):
        if Cerebras and os.getenv("CEREBRAS_API_KEY"):
            self.cerebras = Cerebras(api_key=os.getenv("CEREBRAS_API_KEY"), timeout=config.REQUEST_TIMEOUT, max_retries=1)
        if tiktoken:
            try:
                self.tokenizer = tiktoken.get_encoding("cl100k_base")
            except Exception:
                try:
                    self.tokenizer = tiktoken.get_encoding("gpt2")
                except Exception:
                    self.tokenizer = None
        if Exa and os.getenv("EXA_API_KEY"):
            self.exa = Exa(api_key=os.getenv("EXA_API_KEY"), timeout=config.SEARCH_TIMEOUT)
    def _init_cache_backends(self):
        dsn_env = os.getenv("NEON_DATABASE_URL") or os.getenv("NEON_PSQL_DSN") or ""
        if HAS_PG and dsn_env.startswith("postgres"):
            try:
                self.pg_dsn = dsn_env
                self.pg_pool = ThreadedConnectionPool(minconn=1, maxconn=20, dsn=self.pg_dsn)
                self._ensure_pg_schema()
                logger.info("Postgres cache initialized (Neon).")
            except Exception as e:
                logger.warning(f"Postgres init failed: {e}")
                self.pg_pool = None
    def _ensure_pg_schema(self):
        conn = self.pg_pool.getconn()
        try:
            with conn, conn.cursor() as cur:
                cur.execute("CREATE TABLE IF NOT EXISTS ai_cache (cache_key TEXT PRIMARY KEY, value JSONB NOT NULL, expire_at TIMESTAMPTZ NOT NULL)")
                cur.execute("CREATE INDEX IF NOT EXISTS idx_ai_cache_expire ON ai_cache (expire_at)")
        finally:
            self.pg_pool.putconn(conn)

clients = ClientManager()

@lru_cache(maxsize=10000)
def count_tokens(text: str) -> int:
    if not text:
        return 0
    if clients.tokenizer:
        try:
            return len(clients.tokenizer.encode(text))
        except Exception:
            pass
    return max(1, len(text) // 4)

def fast_sanitize(text: str) -> str:
    return bleach.clean(text or "", tags=[], strip=True).strip()

def fast_validate(query: str) -> bool:
    return bool(query and len(query) > 0)

class Cache:
    _mem_lock = threading.Lock()
    _mem_cache: Dict[str, Tuple[float, Dict[str, Any]]] = {}
    @staticmethod
    def _now_ts() -> float:
        return time.time()
    @staticmethod
    def _ttl_to_ts(ttl_seconds: int) -> float:
        return time.time() + ttl_seconds
    @classmethod
    def get(cls, key: str) -> Optional[Dict[str, Any]]:
        if clients.pg_pool:
            try:
                conn = clients.pg_pool.getconn()
                try:
                    with conn, conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor) as cur:
                        cur.execute("SELECT value FROM ai_cache WHERE cache_key=%s AND expire_at > NOW()", (key,))
                        row = cur.fetchone()
                        if row and row.get("value") is not None:
                            return row["value"]
                finally:
                    clients.pg_pool.putconn(conn)
            except Exception as e:
                logger.warning(f"PG cache get error: {e}")
        with cls._mem_lock:
            item = cls._mem_cache.get(key)
            if item:
                expire_ts, data = item
                if expire_ts > cls._now_ts():
                    return data
                cls._mem_cache.pop(key, None)
        return None
    @classmethod
    def set(cls, key: str, value: Dict[str, Any], ttl_seconds: int = config.CACHE_TTL_SECONDS):
        if clients.pg_pool:
            try:
                conn = clients.pg_pool.getconn()
                try:
                    with conn, conn.cursor() as cur:
                        cur.execute("INSERT INTO ai_cache (cache_key, value, expire_at) VALUES (%s, %s, NOW() + (%s || ' seconds')::INTERVAL) ON CONFLICT (cache_key) DO UPDATE SET value = EXCLUDED.value, expire_at = EXCLUDED.expire_at", (key, json.dumps(value), str(ttl_seconds)))
                finally:
                    clients.pg_pool.putconn(conn)
            except Exception as e:
                logger.warning(f"PG cache set error: {e}")
        with cls._mem_lock:
            if len(cls._mem_cache) > 5000:
                try:
                    cls._mem_cache.pop(next(iter(cls._mem_cache)))
                except Exception:
                    cls._mem_cache.clear()
            cls._mem_cache[key] = (cls._ttl_to_ts(ttl_seconds), value)

def exa_fast_search(query: str):
    return clients.exa.search_and_contents(query=query, num_results=config.MAX_SEARCH_RESULTS, text=True, use_autoprompt=True, type="auto", livecrawl=config.LIVECRAWL, text_contents_options={"max_characters": 50000, "include_html_tags": False})

def process_results_fast(exa_results) -> Tuple[List[Dict[str, Any]], List[str]]:
    if not exa_results or not getattr(exa_results, "results", None):
        return [], []
    results = exa_results.results[: config.MAX_SEARCH_RESULTS]
    processed: List[Dict[str, Any]] = []
    contexts: List[str] = []
    def proc(r):
        title = getattr(r, "title", None) or "No title"
        text = getattr(r, "text", None) or ""
        url = getattr(r, "url", None) or ""
        snippet = text[:500] + ("..." if len(text) > 500 else "")
        context_block = "Source: " + title + "\n" + text[:5000]
        return {"title": title, "snippet": snippet if snippet else "No content", "url": url}, context_block
    with ThreadPoolExecutor(max_workers=config.MAX_WORKERS) as ex:
        futs = [ex.submit(proc, r) for r in results]
        try:
            for f in as_completed(futs, timeout=5):
                try:
                    p, c = f.result()
                    processed.append(p)
                    contexts.append(c)
                except Exception:
                    continue
        except Exception:
            for f in futs:
                if f.done():
                    try:
                        p, c = f.result()
                        processed.append(p)
                        contexts.append(c)
                    except Exception:
                        continue
    total = 0
    trimmed_contexts: List[str] = []
    for c in contexts:
        if total + len(c) > config.MAX_CONTEXT_CHARS:
            break
        trimmed_contexts.append(c)
        total += len(c)
    return processed, trimmed_contexts

def sse_format(data: Dict[str, Any]) -> str:
    line = "data: " + json.dumps(data, ensure_ascii=False)
    return line + "\n\n"

