@app.route("/api/search", methods=["POST"])
def maximum_speed_search():
    data = request.get_json(silent=True) or {}
    if "query" not in data:
        return jsonify({"error": "Hiányzó keresési lekérdezés"}), 400
    query = fast_sanitize(str(data["query"]))
    if not fast_validate(query):
        return jsonify({"error": "Érvénytelen keresési lekérdezés"}), 400
    if not clients.exa:
        return jsonify({"error": "Exa nem elérhető"}), 503
    if not clients.cerebras:
        return jsonify({"error": "Cerebras nem elérhető"}), 503
    stable_hash = hashlib.sha256(query.encode("utf-8")).hexdigest()
    cache_key = "v1:search:" + stable_hash
    cached = Cache.get(cache_key)
    if cached:
        def from_cache():
            yield "retry: " + str(config.SSE_RETRY_MS) + "\n\n"
            if cached.get("ai"):
                yield sse_format({"type": "ai_chunk", "content": cached["ai"]})
            yield sse_format({"type": "search_results", "results": cached.get("results", [])})
            yield sse_format({"type": "complete", "from_cache": True})
        return Response(from_cache(), mimetype="text/event-stream", headers={"X-Accel-Buffering": "no", "Cache-Control": "no-cache"})
    def generate():
        try:
            yield "retry: " + str(config.SSE_RETRY_MS) + "\n\n"
            try:
                exa_results = exa_fast_search(query + " authoritative sources")
            except Exception as e:
                logger.error(f"Exa search error: {e}")
                yield sse_format({"type": "error", "message": "Keresési hiba"})
                return
            processed_results, contexts = process_results_fast(exa_results)
            if not contexts:
                yield sse_format({"type": "error", "message": "Nincs találat"})
                return
            context = "\n\n".join(contexts)
            prompt = "Kérdés: " + query + "\n\nKontextus:\n" + context + "\n\nAdj gyors, pontos és tömör választ magyarul, a lényegre fókuszálva."
            ai_chunks: List[str] = []
            try:
                stream = clients.cerebras.chat.completions.create(messages=[{"role": "user", "content": prompt}], model=config.MODEL_NAME, stream=True, max_completion_tokens=config.MAX_COMPLETION_TOKENS, temperature=config.TEMPERATURE, top_p=config.TOP_P, reasoning={"effort": config.REASONING_EFFORT})
                for chunk in stream:
                    try:
                        content_piece = ""
                        try:
                            if hasattr(chunk, "choices") and chunk.choices:
                                choice0 = chunk.choices[0]
                                if hasattr(choice0, "delta") and choice0.delta and getattr(choice0.delta, "content", None):
                                    content_piece = choice0.delta.content
                                elif getattr(choice0, "text", None):
                                    content_piece = choice0.text
                        except Exception:
                            pass
                        if content_piece:
                            ai_chunks.append(content_piece)
                            yield sse_format({"type": "ai_chunk", "content": content_piece})
                    except Exception:
                        continue
            except Exception as e:
                logger.error(f"AI stream error: {e}")
                yield sse_format({"type": "ai_chunk", "content": "AI válasz nem elérhető, de a találatokat mutatjuk."})
            yield sse_format({"type": "search_results", "results": processed_results})
            try:
                Cache.set(cache_key, {"ai": "".join(ai_chunks), "results": processed_results}, ttl_seconds=config.CACHE_TTL_SECONDS)
            except Exception as e:
                logger.warning(f"Cache persist error: {e}")
            yield sse_format({"type": "complete"})
        except GeneratorExit:
            return
        except Exception as e:
            logger.error(f"Streaming error: {e}")
            yield sse_format({"type": "error", "message": "Váratlan hiba"})
    return Response(generate(), mimetype="text/event-stream", headers={"X-Accel-Buffering": "no", "Cache-Control": "no-cache"})

def signal_handler(sig, frame):
